// src/main.js
var { Plugin, Notice, Modal, Setting } = require("obsidian");
var { scanVault: scanVault2 } = (init_parser(), __toCommonJS(parser_exports));
var { openGraph: openGraph2, writeGraph: writeGraph2, readGraph: readGraph2, runQuery: runQuery2, closeGraph: closeGraph2 } = (init_graphdb(), __toCommonJS(graphdb_exports));
var GRAPH_JSON = "astrolabe/graph.json";
var CypherModal = class extends Modal {
  constructor(app, plugin) {
    super(app);
    this.plugin = plugin;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.createEl("h3", { text: "Cypher \u67E5\u8BE2" });
    const ta = contentEl.createEl("textarea", {
      attr: { rows: "5", placeholder: "MATCH (a:Code)-[:Rel]->(b:Code) RETURN a.name, b.name LIMIT 20" }
    });
    ta.style.width = "100%";
    ta.style.fontFamily = "monospace";
    ta.style.fontSize = "12px";
    ta.value = "MATCH (c:Code) RETURN c.kind AS kind, count(*) AS n ORDER BY n DESC";
    const out2 = contentEl.createEl("pre");
    out2.style.marginTop = "10px";
    out2.style.maxHeight = "320px";
    out2.style.overflow = "auto";
    out2.style.fontSize = "11px";
    out2.setText("\uFF08\u7ED3\u679C\u4F1A\u663E\u793A\u5728\u8FD9\u91CC\uFF09");
    const btn = contentEl.createEl("button", { text: "\u6267\u884C" });
    btn.style.marginTop = "8px";
    btn.onclick = async () => {
      out2.setText("\u6267\u884C\u4E2D\u2026");
      try {
        const { columns, rows, elapsedMs } = await this.plugin.query(ta.value);
        if (!rows.length) {
          out2.setText(`\uFF080 \u884C\uFF0C${elapsedMs}ms\uFF09`);
          return;
        }
        const head = columns.join(" | ");
        const body2 = rows.slice(0, 200).map((r) => columns.map((c) => String(r[c] ?? "")).join(" | ")).join("\n");
        const more = rows.length > 200 ? `
\u2026 \u8FD8\u6709 ${rows.length - 200} \u884C` : "";
        out2.setText(`${head}
${"-".repeat(Math.min(80, head.length))}
${body2}${more}

\uFF08${rows.length} \u884C\uFF0C${elapsedMs}ms\uFF09`);
      } catch (e) {
        out2.setText(`\u9519\u8BEF\uFF1A${String(e && e.message || e)}`);
      }
    };
    ta.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter" && (ev.ctrlKey || ev.metaKey)) {
        ev.preventDefault();
        btn.click();
      }
    });
    ta.focus();
  }
  onClose() {
    this.contentEl.empty();
  }
};
var AstrolabePlugin = class extends Plugin {
  async onload() {
    console.log("[ASTROLABE] plugin loaded");
    this.graph = null;
    this.addCommand({
      id: "parse-vault",
      name: "\u89E3\u6790\u5F53\u524D vault \u4EE3\u7801\uFF08\u5199\u5165 graph.json + \u56FE\u5E93\uFF09",
      callback: () => this.runParse()
    });
    this.addCommand({
      id: "cypher-query",
      name: "Cypher \u67E5\u8BE2",
      callback: () => new CypherModal(this.app, this).open()
    });
    this.addCommand({
      id: "reload-graph",
      name: "\u4ECE graph.json \u91CD\u5EFA\u56FE\u5E93",
      callback: () => this.reloadFromJson()
    });
    this.app.workspace.onLayoutReady(() => {
      void this.reloadFromJson({ silent: true });
    });
  }
  async onunload() {
    console.log("[ASTROLABE] plugin unloaded");
    if (this.graph) {
      try {
        await closeGraph2(this.graph);
      } catch {
      }
      this.graph = null;
    }
  }
  /** 写 JSON 到 vault（目录不存在时先建） */
  async saveJson(payload) {
    const adapter = this.app.vault.adapter;
    const dir = "astrolabe";
    if (!await adapter.exists(dir)) await adapter.mkdir(dir);
    await adapter.write(GRAPH_JSON, JSON.stringify(payload));
  }
  /** 从 graph.json 重建内存图库 */
  async reloadFromJson({ silent = false } = {}) {
    const adapter = this.app.vault.adapter;
    if (!await adapter.exists(GRAPH_JSON)) {
      if (!silent) new Notice("\u6CA1\u6709\u627E\u5230 astrolabe/graph.json\uFF0C\u5148\u8FD0\u884C\u300C\u89E3\u6790\u5F53\u524D vault \u4EE3\u7801\u300D");
      return false;
    }
    try {
      const text = await adapter.read(GRAPH_JSON);
      const data = JSON.parse(text);
      if (this.graph) {
        try {
          await closeGraph2(this.graph);
        } catch {
        }
        this.graph = null;
      }
      const project = (this.app.vault.getName() || "vault").replace(/[^\w\u4e00-\u9fa5-]/g, "_");
      const g = await openGraph2(project);
      await writeGraph2(g.conn, data.nodes || [], data.edges || []);
      this.graph = g;
      if (!silent) {
        new Notice(`\u56FE\u5E93\u5DF2\u91CD\u5EFA\uFF1A${(data.nodes || []).length} \u8282\u70B9 / ${(data.edges || []).length} \u8FB9`);
      }
      console.log("[ASTROLABE] reloaded from json", g.dbPath);
      return true;
    } catch (e) {
      console.error("[ASTROLABE] reload failed", e);
      if (!silent) new Notice(`\u91CD\u5EFA\u5931\u8D25\uFF1A${String(e && e.message || e)}`);
      return false;
    }
  }
  /** 确保内存库可用（没有就从 JSON 建） */
  async ensureGraph() {
    if (this.graph) return this.graph;
    const ok = await this.reloadFromJson({ silent: true });
    if (!ok) throw new Error("\u56FE\u5E93\u672A\u5C31\u7EEA\uFF0C\u8BF7\u5148\u8FD0\u884C\u300C\u89E3\u6790\u5F53\u524D vault \u4EE3\u7801\u300D");
    return this.graph;
  }
  /** 执行 Cypher */
  async query(cypher) {
    const g = await this.ensureGraph();
    return runQuery2(g.conn, cypher);
  }
  async runParse() {
    const notice = new Notice("Astrolabe: \u521D\u59CB\u5316 WASM \u89E3\u6790\u5668\u2026", 0);
    try {
      const t0 = Date.now();
      const result = await scanVault2(this.app, this.manifest.dir, { maxFiles: 500 });
      notice.setMessage("Astrolabe: \u5199\u5165 astrolabe/graph.json \u2026");
      await this.saveJson({
        generatedAt: (/* @__PURE__ */ new Date()).toISOString(),
        files: result.files,
        scanned: result.scanned,
        nodes: result.nodes,
        edges: result.edges
      });
      notice.setMessage("Astrolabe: \u6784\u5EFA\u56FE\u5E93 \u2026");
      if (this.graph) {
        try {
          await closeGraph2(this.graph);
        } catch {
        }
        this.graph = null;
      }
      const project = (this.app.vault.getName() || "vault").replace(/[^\w\u4e00-\u9fa5-]/g, "_");
      const g = await openGraph2(project);
      await writeGraph2(g.conn, result.nodes, result.edges);
      this.graph = g;
      const ms = Date.now() - t0;
      const kinds = {};
      for (const n of result.nodes) kinds[n.kind] = (kinds[n.kind] || 0) + 1;
      const summary = `\u6587\u4EF6 ${result.files}/${result.scanned} \xB7 \u8282\u70B9 ${result.nodes.length} \xB7 \u8FB9 ${result.edges.length} \xB7 ${ms}ms
${Object.entries(kinds).map(([k, v]) => `${k}:${v}`).join(" ")}
\u5B58\u6863: ${GRAPH_JSON}`;
      notice.setMessage(`Astrolabe \u89E3\u6790\u5B8C\u6210
${summary}`);
      console.log("[ASTROLABE] parse done", summary);
      setTimeout(() => notice.hide(), 2e4);
    } catch (e) {
      const msg = String(e && e.message || e);
      notice.setMessage(`Astrolabe \u89E3\u6790\u5931\u8D25\uFF1A${msg}`);
      console.error("[ASTROLABE] parse error", e);
      setTimeout(() => notice.hide(), 2e4);
    }
  }
};
module.exports = AstrolabePlugin;
